import subprocess
import tempfile
from pathlib import Path

import requests


def _transcode(source: Path, target: Path, max_height: int) -> None:
    cmd = [
        "ffmpeg", "-y", "-i", str(source),
        "-vf", f"scale=-2:'min({max_height},ih)'",
        "-c:v", "libx264", "-crf", "28",
        "-c:a", "aac", "-b:a", "128k",
        str(target),
    ]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError(result.stderr[-500:])


def upload_video_transcode_and_notify(video_path: str, upload_url: str, webhook_url: str, max_height: int = 720) -> dict:
    source = Path(video_path)
    if not source.is_file():
        return {"ok": False, "error": "video not found"}
    with tempfile.TemporaryDirectory() as tmp:
        target = Path(tmp) / (source.stem + "_web.mp4")
        try:
            _transcode(source, target, max_height)
        except RuntimeError as exc:
            return {"ok": False, "error": str(exc)}
        size = target.stat().st_size
        with open(target, "rb") as fh:
            resp = requests.post(
                upload_url,
                files={"file": (target.name, fh, "video/mp4")},
                timeout=300,
            )
    resp.raise_for_status()
    link = resp.json().get("url")
    hook = requests.post(
        webhook_url,
        json={"title": source.stem, "link": link, "size_bytes": size},
        timeout=30,
    )
    return {"ok": True, "link": link, "size_bytes": size, "webhook_status": hook.status_code}

import sqlite3
from dataclasses import dataclass
from typing import Optional

from agents import tool

DB_PATH = "library.db"


@dataclass
class RatingResult:
    photo_id: int
    old_rating: Optional[int]
    new_rating: int


@tool
def tag_photo_with_rating(photo_id: int, rating: int) -> RatingResult:
    if not 0 <= rating <= 5:
        raise ValueError("rating must be between 0 and 5")
    with sqlite3.connect(DB_PATH) as conn:
        row = conn.execute("SELECT rating FROM photos WHERE id = ?", (photo_id,)).fetchone()
        if row is None:
            raise LookupError(f"photo {photo_id} not found")
        conn.execute("UPDATE photos SET rating = ?, modified_at = CURRENT_TIMESTAMP WHERE id = ?", (rating, photo_id))
    return RatingResult(photo_id, row[0], rating)

import subprocess
from contextlib import contextmanager
from pathlib import Path

from agents import tool


@contextmanager
def _log_file(name: str):
    path = Path.home() / ".photo_backup_logs"
    path.mkdir(exist_ok=True)
    fh = open(path / f"{name}.log", "w", encoding="utf-8")
    try:
        yield fh
    finally:
        fh.close()


@tool
def run_album_backup_sync(album_dir: str, remote: str) -> dict:
    source = Path(album_dir)
    if not source.is_dir():
        return {"ok": False, "error": "album folder not found"}
    with _log_file(source.name) as log:
        proc = subprocess.run(
            ["rclone", "copy", str(source), remote, "--stats-one-line", "-v"],
            stdout=log,
            stderr=subprocess.STDOUT,
            text=True,
        )
    return {"ok": proc.returncode == 0, "exit_code": proc.returncode, "log": source.name + ".log"}
